import pandas as pd

def clean_val(val):
    if pd.isna(val):
        return 0.0
    if isinstance(val, (int, float)):
        return float(val)
    val_str = str(val).replace('$', '').replace(',', '').strip()
    if val_str.startswith('(') and val_str.endswith(')'):
        return -float(val_str[1:-1])
    return float(val_str)

